import{_ as i,o as l,c as r,a3 as o}from"./chunks/framework.D8u9WiMi.js";const d=JSON.parse('{"title":"ai应用岗位开发","description":"","frontmatter":{},"headers":[],"relativePath":"resource/ai-app-dev.md","filePath":"resource/ai-app-dev.md"}'),t={name:"resource/ai-app-dev.md"};function n(e,a,s,p,g,h){return l(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="ai应用岗位开发" tabindex="-1">ai应用岗位开发 <a class="header-anchor" href="#ai应用岗位开发" aria-label="Permalink to &quot;ai应用岗位开发&quot;">​</a></h1><p>01_尚硅谷大模型技术之Python基础</p><p>02_尚硅谷大模型技术之数据结构与算法</p><p>03_尚硅谷大模型技术之Linux及Shell</p><p>04_尚硅谷大模型技术之MySQL</p><p>05_尚硅谷大模型技术之Numpy&amp;Pandas</p><p>06尚硅谷大模型技术之Git</p><p>07尚硅谷大模型技术之机器学习核心</p><p>08尚硅谷大模型技术之深度学习核心</p><p>09_尚硅谷大模型项目之智图寻宝</p><p>10尚硅谷大模型技术之NLP</p><p>11_尚硅谷大模型项目之智能商品发布</p><p>12_尚硅谷大模型项目实战之地址对齐</p><p>13_尚硅谷大模型项目实战之智选新闻</p><p>14_尚硅谷大模型技术之langchain</p><p>15_尚硅谷大模型项目之电商图谱</p><p>16_尚硅谷大模型项目实战之AI智教</p><p>17_尚硅谷大模型项目实战之智医助手</p><p>18尚硅谷大模型技术之Coze+Dify平台智能体开发实战</p><p>19_尚硅谷大模型技术之LLM</p><p>20_尚硅谷大模型技术之强化学习</p><p>21_尚硅谷大模型技术之多模态</p><p>22_尚硅谷大模型技术之langgraph</p><p>23_尚硅谷大模型项目之点餐智能体</p><p>24_尚硅谷大模型项目之ITS多智能体</p><p>25_尚硅谷大模型项目之掌柜问数</p><p>26_尚硅谷大模型项目之智能客服系统</p><br><br><h1 id="ai应用开发岗位学习路径分析与补充建议" tabindex="-1">AI应用开发岗位学习路径分析与补充建议 <a class="header-anchor" href="#ai应用开发岗位学习路径分析与补充建议" aria-label="Permalink to &quot;AI应用开发岗位学习路径分析与补充建议&quot;">​</a></h1><h2 id="现有学习路径评估" tabindex="-1">现有学习路径评估 <a class="header-anchor" href="#现有学习路径评估" aria-label="Permalink to &quot;现有学习路径评估&quot;">​</a></h2><p>你提供的学习路径已经非常全面，涵盖了AI开发的核心技术栈：</p><ul><li><strong>基础技能</strong>：Python、数据结构与算法、Linux、MySQL、Git</li><li><strong>数据处理</strong>：Numpy、Pandas</li><li><strong>AI核心技术</strong>：机器学习、深度学习、NLP、LLM、强化学习、多模态</li><li><strong>框架与工具</strong>：LangChain、LangGraph、Coze+Dify</li><li><strong>项目实战</strong>：多个行业应用场景的项目</li></ul><h2 id="市场需求分析" tabindex="-1">市场需求分析 <a class="header-anchor" href="#市场需求分析" aria-label="Permalink to &quot;市场需求分析&quot;">​</a></h2><p>根据当前AI应用开发岗位的市场需求，你确实需要补充<strong>Web框架和服务器知识</strong>，原因如下：</p><ol><li><strong>AI模型部署需求</strong>：训练好的模型需要通过Web服务对外提供API</li><li><strong>前端交互需求</strong>：AI应用需要用户友好的界面</li><li><strong>生产环境部署</strong>：需要了解服务器配置、负载均衡等知识</li><li><strong>全栈开发能力</strong>：企业更倾向于招聘能够独立完成从模型到应用的全栈开发者</li></ol><h2 id="建议补充的知识点" tabindex="-1">建议补充的知识点 <a class="header-anchor" href="#建议补充的知识点" aria-label="Permalink to &quot;建议补充的知识点&quot;">​</a></h2><h3 id="_1-web框架" tabindex="-1">1. Web框架 <a class="header-anchor" href="#_1-web框架" aria-label="Permalink to &quot;1. Web框架&quot;">​</a></h3><ul><li><strong>Python Web框架</strong>： <ul><li>FastAPI（推荐，性能优异，适合API开发）</li><li>Flask（轻量级，灵活）</li><li>Django（全功能，适合大型应用）</li></ul></li><li><strong>API设计</strong>：RESTful API设计原则、GraphQL</li></ul><h3 id="_2-服务器与部署" tabindex="-1">2. 服务器与部署 <a class="header-anchor" href="#_2-服务器与部署" aria-label="Permalink to &quot;2. 服务器与部署&quot;">​</a></h3><ul><li><strong>容器化</strong>：Docker、Docker Compose</li><li><strong>编排</strong>：Kubernetes基础</li><li><strong>云服务</strong>：AWS、Azure、阿里云等云平台基础</li><li><strong>CI/CD</strong>：GitHub Actions、Jenkins</li><li><strong>监控</strong>：Prometheus、Grafana</li></ul><h3 id="_3-前端基础" tabindex="-1">3. 前端基础 <a class="header-anchor" href="#_3-前端基础" aria-label="Permalink to &quot;3. 前端基础&quot;">​</a></h3><ul><li><strong>前端框架</strong>：React、Vue（至少掌握一种）</li><li><strong>API调用</strong>：Axios、Fetch API</li><li><strong>状态管理</strong>：Redux、Vuex</li><li><strong>响应式设计</strong>：Tailwind CSS、Bootstrap</li></ul><h3 id="_4-数据库与缓存" tabindex="-1">4. 数据库与缓存 <a class="header-anchor" href="#_4-数据库与缓存" aria-label="Permalink to &quot;4. 数据库与缓存&quot;">​</a></h3><ul><li><strong>NoSQL数据库</strong>：MongoDB、Redis</li><li><strong>缓存策略</strong>：Redis缓存、CDN</li><li><strong>数据管道</strong>：消息队列（RabbitMQ、Kafka）</li></ul><h3 id="_5-安全与性能" tabindex="-1">5. 安全与性能 <a class="header-anchor" href="#_5-安全与性能" aria-label="Permalink to &quot;5. 安全与性能&quot;">​</a></h3><ul><li><strong>API安全</strong>：JWT、OAuth2.0</li><li><strong>数据安全</strong>：加密、脱敏</li><li><strong>性能优化</strong>：模型压缩、边缘计算</li><li><strong>负载均衡</strong>：Nginx、负载均衡策略</li></ul><h2 id="学习路径优化建议" tabindex="-1">学习路径优化建议 <a class="header-anchor" href="#学习路径优化建议" aria-label="Permalink to &quot;学习路径优化建议&quot;">​</a></h2><p>在现有学习路径基础上，建议按以下顺序补充：</p><ol><li><strong>Web框架</strong>：在完成Python基础后学习FastAPI或Flask</li><li><strong>数据库扩展</strong>：在MySQL基础上学习MongoDB和Redis</li><li><strong>部署知识</strong>：在Linux基础上学习Docker和云服务</li><li><strong>前端基础</strong>：学习React或Vue基础</li><li><strong>整合实践</strong>：将AI模型通过Web服务部署，并构建前端界面</li></ol><h2 id="就业竞争力提升" tabindex="-1">就业竞争力提升 <a class="header-anchor" href="#就业竞争力提升" aria-label="Permalink to &quot;就业竞争力提升&quot;">​</a></h2><ol><li><strong>作品集准备</strong>： <ul><li>部署至少2-3个完整的AI应用（包含前端和后端）</li><li>提供GitHub仓库链接</li><li>准备项目演示视频</li></ul></li><li><strong>技术栈整合</strong>： <ul><li>掌握从数据处理、模型训练到部署上线的完整流程</li><li>了解MLOps（机器学习运维）基础</li></ul></li><li><strong>行业知识</strong>： <ul><li>了解目标行业的业务流程</li><li>关注行业特定的AI应用场景</li></ul></li></ol><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>你提供的学习路径已经非常全面，涵盖了AI核心技术。通过补充Web框架、服务器和前端知识，你将具备从模型开发到应用部署的全栈能力，大大提升在AI应用开发岗位的竞争力。</p><p>建议将这些补充内容整合到现有学习路径中，形成一个更加完整的AI应用开发技能体系，以更好地应对市场需求。</p>',55)])])}const _=i(t,[["render",n]]);export{d as __pageData,_ as default};
